function applyResultsViewLanguage(){
 const words=RESULTS_VIEW_UI[lang]||RESULTS_VIEW_UI.en;
 document.querySelectorAll('[data-results-view]').forEach(el=>{const key=el.dataset.resultsView;if(words[key])el.textContent=words[key];});
 document.querySelectorAll('.results-stream-links:not(.preference-page-switcher)').forEach(nav=>nav.setAttribute('aria-label',words.streams));
 if(!document.querySelector('.preference-page-switcher'))document.querySelectorAll('.results-view-tabs').forEach(nav=>nav.setAttribute('aria-label',words.viewsAria));
 const answerNumber=document.querySelector('#answer-number-input');
 if(answerNumber)answerNumber.setAttribute('aria-label',words.answerNumberAria);
 const streamLinks=document.querySelectorAll('.results-stream-links:not(.preference-page-switcher) .results-stream-link');
 const streamKeys=[['streamCollective','streamCollectiveDesc'],['streamPersonal','streamPersonalDesc']];
 streamLinks.forEach((link,index)=>{const text=link.querySelector('span:nth-child(2)');if(!text)return;const strong=text.querySelector('strong');const small=text.querySelector('small');if(strong)strong.textContent=words[streamKeys[index]?.[0]]||strong.textContent;if(small)small.textContent=words[streamKeys[index]?.[1]]||small.textContent;});
 const picker=document.querySelector('label[for="results-question-select"]');
 if(picker)picker.textContent=words.questionLabel;
 const questionOptions={q2:'collectiveQ2',q3:'collectiveQ3',q4:'collectiveQ4'};
 document.querySelectorAll('#results-question-select option').forEach(option=>{const key=questionOptions[option.value];if(key&&words[key])option.textContent=words[key];});
 const pageSize=document.querySelector('label[for="answers-per-page"]');
 if(pageSize){const select=pageSize.querySelector('select');pageSize.textContent=words.pageSize+' ';if(select)pageSize.append(select);}
 const previous=document.querySelector('#answers-previous');
 if(previous)previous.textContent=words.previous;
 const personalSearch=document.querySelector('#hypothetical-search');
 if(personalSearch){personalSearch.placeholder=words.searchPersonal;const label=personalSearch.closest('label')?.querySelector('.sr-only');if(label)label.textContent=words.searchPersonal;}
 const questionFilter=document.querySelector('#hypothetical-question-filter');
 if(questionFilter){const options={ '':'allQuestions',scope:'questionScope',motivation:'questionMotivation',priority:'priority',preserve:'preserve',wishes:'wishes',body:'body'};questionFilter.querySelectorAll('option').forEach(option=>{const key=options[option.value];if(key&&words[key])option.textContent=words[key];});const hiddenLabel=questionFilter.closest('label')?.querySelector('.sr-only');if(hiddenLabel)hiddenLabel.textContent=words.questionLabel;}
 const sort=document.querySelector('#hypothetical-sort');
 if(sort){const label=sort.closest('label')?.querySelector('.sr-only');if(label)label.textContent=words.sort;sort.querySelectorAll('option').forEach(option=>{if(option.value==='latest')option.textContent=(UI[lang]||UI.en).newest;else if(option.value==='oldest')option.textContent=(UI[lang]||UI.en).oldest;});}
 const personalPageSize=document.querySelector('.hypothetical-page-size');
 if(personalPageSize){const select=personalPageSize.querySelector('select');personalPageSize.firstChild.textContent=words.pageSize+' ';if(select)personalPageSize.append(select);}
 const notice=document.querySelector('.hypothetical-data-notice');
 if(notice)notice.textContent=words.personalNotice;
}function applyPreferenceResearchLanguage(){const words=PREFERENCE_RESEARCH_UI[lang]||PREFERENCE_RESEARCH_UI.en;document.querySelectorAll('[data-voice]').forEach(el=>{const key=el.dataset.voice;if(typeof words[key]!=='string')return;const link=el.querySelector('.author-answer-shortcut');if(link){el.childNodes.forEach(node=>{if(node!==link)node.remove();});el.insertBefore(document.createTextNode(words[key]+' '),link);}else{el.textContent=words[key];}});}
function applyLanguage(){const words=t();document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.querySelectorAll('[data-t]').forEach(el=>{const k=el.dataset.t;if(typeof words[k]==='string')el.textContent=words[k];});document.querySelectorAll('[data-placeholder]').forEach(el=>el.placeholder=words[el.dataset.placeholder]||UI.en[el.dataset.placeholder]||'');document.querySelectorAll('[data-topic]').forEach(el=>el.textContent=words.topics?.[el.dataset.topic]||UI.en.topics[el.dataset.topic]);const select=$('#page-language');if(select){select.value=lang;const languageLabels={en:'Language',ru:'Язык',es:'Idioma',pt:'Idioma',zh:'语言',de:'Sprache',ja:'言語',fr:'Langue',ar:'اللغة'};select.setAttribute('aria-label',languageLabels[lang]||languageLabels.en);}$('#date-from')?.setAttribute('aria-label',words.fromLabel);$('#date-to')?.setAttribute('aria-label',words.toLabel);$('#results-back').textContent=words.back;document.title=`${(document.querySelector('.preference-page-switcher')?PREFERENCE_RESEARCH_UI[lang]?.resultsTitle:words.answersTitle)||words.answersTitle} - THE HUMAN EXPERIMENT`;applyOpenDataLanguage();applyAIAnalysisLanguage();applyPreferenceResearchLanguage();applyResultsViewLanguage();document.dispatchEvent(new Event('results-language-changed'));}
function translateOption(label){const pair=String(label||'').split(' / ');return lang==='ru'?(pair[1]||pair[0]):pair[0];}
function makeBars(target,items){const root=$('#'+target);root.replaceChildren();const answered=(items||[]).reduce((n,item)=>n+Number(item.count||0),0);(items||[]).forEach(item=>{const pct=answered?Math.round(Number(item.count)/answered*100):0;const row=document.createElement('div');row.className='bar-row';const label=document.createElement('div');label.className='bar-label';label.textContent=translateOption(item.label);const value=document.createElement('div');value.className='bar-value';value.textContent=`${Number(item.count).toLocaleString(lang)} · ${pct}%`;const track=document.createElement('div');track.className='bar-track';const fill=document.createElement('div');fill.className='bar-fill';fill.style.width=`${pct}%`;track.append(fill);row.append(label,value,track);root.append(row);});}
async function loadStats(){const status=$('#results-status');if(DEMO_MODE){ensureDemoNotices();const root=$('#author-answer-collective');const hypothetical=$('#author-answer-hypothetical');if(root)root.dataset.resultsUnlocked='true';if(hypothetical)hypothetical.dataset.resultsUnlocked='true';status.hidden=true;$('#results-content').hidden=false;$('#stats-state').textContent=t().statsOpen;$('#total-responses').textContent='101';const demoUpdatedLabels={en:'Demo data · 101 responses',ru:'Демонстрационные данные · 101 ответ',es:'Datos de demostración · 101 respuestas',pt:'Dados de demonstração · 101 respostas',zh:'演示数据 · 101 条回答',de:'Demodaten · 101 Antworten',ja:'デモデータ · 101件の回答',fr:'Données de démonstration · 101 réponses',ar:'بيانات تجريبية · 101 إجابة'};$('#updated-at').textContent=demoUpdatedLabels[lang]||demoUpdatedLabels.en;const optionLang=lang==='ru'?'ru':'en';const demoCounts={q2:[22,18,14,17,8,12,10],q3:[28,31,16,17,9],q4:[18,21,12,14,13,8,15]};for(const [question,chart] of [['q2','chart-q2'],['q3','chart-q3'],['q4','chart-q4']]){const bars=QUESTION_OPTIONS[question][optionLang].map((label,index)=>({label,count:demoCounts[question][index]}));makeBars(chart,bars);}syncCollectiveAuthorAnswer();return;}try{const res=await fetch('/api/results');const data=await res.json();if(!res.ok)throw Error();if(!data.unlocked){const root=$('#author-answer-collective');const hypothetical=$('#author-answer-hypothetical');if(root){root.dataset.resultsUnlocked='false';}if(hypothetical){hypothetical.dataset.resultsUnlocked='false';}syncCollectiveAuthorAnswer();$('#total-responses').textContent=Number(data.total).toLocaleString(lang);const total=Number(data.total).toLocaleString(lang),threshold=Number(data.threshold).toLocaleString(lang),remaining=Number(data.remaining).toLocaleString(lang);const remainingLabel=$statusWords().remaining;status.textContent=`${t().locked(data.threshold)} \u2066${total} / ${threshold} (${remaining} ${remainingLabel})\u2069`;$('#stats-state').textContent=t().statsLocked;return;}const root=$('#author-answer-collective');const hypothetical=$('#author-answer-hypothetical');if(root){root.dataset.resultsUnlocked='true';}if(hypothetical){hypothetical.dataset.resultsUnlocked='true';}syncCollectiveAuthorAnswer();status.hidden=true;$('#results-content').hidden=false;$('#stats-state').textContent=t().statsOpen;$('#total-responses').textContent=Number(data.total).toLocaleString(lang);$('#updated-at').textContent=`${t().updated}: ${new Date(data.updatedAt).toLocaleString(lang)}${data.nextThreshold?` · ${$statusWords().nextUpdate} ${Number(data.nextThreshold).toLocaleString(lang)}`:''}`;makeBars('chart-q2',data.q2);makeBars('chart-q3',data.q3);makeBars('chart-q4',data.q4);}catch{status.textContent=t().unavailable;}}
function syncFiltersToUrl(){const url=new URL(location.href);const params=url.searchParams;for(const key of ['q','topic','choice','from','to','sort'])params.delete(key);const q=$('#answer-search').value.trim();if(q)params.set('q',q);if($('#topic-filter').value)params.set('choice',$('#topic-filter').value);if($('#date-from').value)params.set('from',$('#date-from').value);if($('#date-to').value)params.set('to',$('#date-to').value);if($('#answer-sort').value&&$('#answer-sort').value!=='oldest')params.set('sort',$('#answer-sort').value);history.replaceState({},'',url);}
function restoreFiltersFromUrl(){const params=new URL(location.href).searchParams;$('#answer-search').value=params.get('q')||'';$('#topic-filter').value=params.get('choice')||'';$('#date-from').value=params.get('from')||'';$('#date-to').value=params.get('to')||'';const sort=params.get('sort')||'newest';$('#answer-sort').value=['newest','oldest','popular','random','unusual'].includes(sort)?sort:'newest';}
function syncParticipantMode(){$('#all-participants').hidden=!new URL(location.href).searchParams.has('participant');}
window.addEventListener('popstate',()=>{populateQuestionFilter();restoreFiltersFromUrl();syncParticipantMode();loadAnswers(true).then(()=>loadLinkedAnswer());});
window.addEventListener('hashchange',()=>loadLinkedAnswer());
function queryString(){const params=new URLSearchParams({limit:String(pageSize),offset:String(offset),sort:$('#answer-sort').value});const currentUrl=new URL(location.href);if(currentUrl.searchParams.has('participant'))params.set('participant',currentUrl.searchParams.get('participant')||'');if($('#answer-search').value.trim())params.set('q',$('#answer-search').value.trim());if($('#topic-filter').value)params.set('choice',$('#topic-filter').value);if($('#date-from').value)params.set('from',$('#date-from').value);if($('#date-to').value)params.set('to',$('#date-to').value);return params.toString();}
